#!/usr/bin/env python3
import sys
import base64
import marshal
import types

try:
    from Crypto.Cipher import AES
    from Crypto.Util.Padding import unpad
except ImportError:
    print("PyCryptodome tidak ada. Install: pip install pycryptodome")
    sys.exit(1)

key = bytes.fromhex("8569d43712fbb519139aa5deb5a526d6d372753759382f57559da55c1b17965d")
enc_data = base64.b64decode("")
iv = enc_data[:16]
ct = enc_data[16:]
cipher = AES.new(key, AES.MODE_CBC, iv)
plain = unpad(cipher.decrypt(ct), AES.block_size)
code_obj = marshal.loads(plain)
fn = types.FunctionType(code_obj, globals(), 'obfuscated_main')
fn()
